const listVouchers = `-- name: ListVouchers :many

SELECT v.id, v.doc_no, v.voucher_date, v.source_type, v.source_id, v.source_no, v.description, v.status,
       v.reversal_of, v.total_amount, v.version, v.updated_at, cu.name AS created_by_name,
       EXISTS (SELECT 1 FROM vouchers r WHERE r.reversal_of = v.id) AS reversed
FROM vouchers v LEFT JOIN users cu ON cu.id = v.created_by
WHERE v.company_id = $1
  AND ($2::text IS NULL OR v.status = $2)
  AND ($3::text IS NULL OR ($3 = 'manual' AND v.source_type = 'manual')
       OR ($3 = 'auto' AND v.source_type <> 'manual'))
  AND ($4::text IS NULL OR v.doc_no ILIKE '%' || $4 || '%'
       OR v.source_no ILIKE '%' || $4 || '%' OR v.description ILIKE '%' || $4 || '%')
  AND ($5::date IS NULL OR v.voucher_date >= $5)
  AND ($6::date IS NULL OR v.voucher_date <= $6)
  AND ($7::bigint IS NULL OR EXISTS (
        SELECT 1 FROM voucher_lines l WHERE l.voucher_id = v.id AND l.account_id = $7))
ORDER BY v.voucher_date DESC, v.id DESC
LIMIT $9 OFFSET $8
`

type ListVouchersParams struct {
	CompanyID int64
	Status    *string
	Source    *string
	Keyword   *string
	FromDate  *time.Time
	ToDate    *time.Time
	AccountID *int64
	Off       int32
	Lim       int32
}

type ListVouchersRow struct {
	ID            int64
	DocNo         string
	VoucherDate   time.Time
	SourceType    string
	SourceID      *int64
	SourceNo      string
	Description   string
	Status        string
	ReversalOf    *int64
	TotalAmount   decimal.Decimal
	Version       int32
	UpdatedAt     time.Time
	CreatedByName *string
	Reversed      bool
}

// ======== 傳票 ========
func (q *Queries) ListVouchers(ctx context.Context, arg ListVouchersParams) ([]ListVouchersRow, error) {
	rows, err := q.db.Query(ctx, listVouchers,
		arg.CompanyID,
		arg.Status,
		arg.Source,
		arg.Keyword,
		arg.FromDate,
		arg.ToDate,
		arg.AccountID,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListVouchersRow{}
	for rows.Next() {
		var i ListVouchersRow
		if err := rows.Scan(
			&i.ID,
			&i.DocNo,
			&i.VoucherDate,
			&i.SourceType,
			&i.SourceID,
			&i.SourceNo,
			&i.Description,
			&i.Status,
			&i.ReversalOf,
			&i.TotalAmount,
			&i.Version,
			&i.UpdatedAt,
			&i.CreatedByName,
			&i.Reversed,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

