const trialBalance = `-- name: TrialBalance :many

SELECT a.id AS account_id, a.code, a.name, a.acct_type,
       COALESCE(SUM(l.debit - l.credit) FILTER (WHERE v.voucher_date < $1::date), 0)::numeric AS opening,
       COALESCE(SUM(l.debit) FILTER (WHERE v.voucher_date BETWEEN $1::date AND $2::date), 0)::numeric AS period_debit,
       COALESCE(SUM(l.credit) FILTER (WHERE v.voucher_date BETWEEN $1::date AND $2::date), 0)::numeric AS period_credit
FROM accounts a
JOIN voucher_lines l ON l.account_id = a.id
JOIN vouchers v ON v.id = l.voucher_id AND v.status = 'posted' AND v.voucher_date <= $2::date
WHERE a.company_id = $3
GROUP BY a.id
ORDER BY a.code
`

type TrialBalanceParams struct {
	FromDate  time.Time
	ToDate    time.Time
	CompanyID int64
}

